 function readSettings(){p.category=$('#post-category').value;p.font=$('#post-font').value;p.relatedMode=$('#related-mode').value;p.related=$$('[data-related]:checked').map(el=>el.value);if(current.type==='portfolio'){p.style=$('#post-style').value.trim();p.kind=$('#post-kind').value.trim();p.points=$('#post-points').value.split(',').map(s=>s.trim()).filter(Boolean);p.isActual=$('#post-actual').checked;p.showNote=$('#show-note').checked;p.price={mode:$('#price-mode').value,unit:$('#price-unit').value.trim(),total:$('#price-total').value.trim()};}$('#unit-label').hidden=!['unit','both'].includes(p.price?.mode);$('#total-label').hidden=!['total','both'].includes(p.price?.mode);$('#related-choices').hidden=p.relatedMode!=='manual';if(p.blocks[active]?.type==='image'){p.blocks[active].size=$('#image-size').value;p.blocks[active].align=$('#image-align').value;}}
